package com.taylordproductivty.med_timing_tracker.notifications

import android.content.BroadcastReceiver
import android.content.Context
import android.content.Intent
import com.taylordproductivty.med_timing_tracker.data.AppDatabase
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.launch

class BootReminderReceiver : BroadcastReceiver() {
    override fun onReceive(context: Context, intent: Intent) {
        if (intent.action != Intent.ACTION_BOOT_COMPLETED) return
        val pendingResult = goAsync()
        val appContext = context.applicationContext
        CoroutineScope(Dispatchers.IO).launch {
            try {
                val database = AppDatabase.getDatabase(appContext)
                val now = System.currentTimeMillis()
                val pending = database.doseLogDao().getPendingReminders(now)
                for (doseLog in pending) {
                    val medication = database.medicationDao().getById(doseLog.medicationId) ?: continue
                    ExactAlarmScheduler.schedule(
                        appContext,
                        doseLog.id,
                        doseLog.nextEligibleAtEpochMillis ?: continue,
                        "Dose window open",
                        "${medication.name} is now eligible for another dose",
                    )
                }
            } finally {
                pendingResult.finish()
            }
        }
    }
}
